#include <bits/stdc++.h>
#define rep1(i, l, r) for (int i = l; i <= int(r); ++i)
using namespace std;
const int MAXN = 1e6 + 10, inf = ~0U >> 2;
int n, vis[MAXN], chg[8010]; vector <int> a[8010];

void init(vector <int> &now) {
    for (auto &v : now) cin >> v, vis[v] = 0;
    reverse(begin(now), end(now));
    vector <int> nw;
    for (auto v : now) if (!vis[v]) nw.emplace_back(v), vis[v] = 1;
    for (auto v : nw) vis[v] = 0;
    now = nw;
}

void change(vector <int> &now) {
    if (now.size() == 1 && now[0] == inf) return;
    vector <int> nw;
    for (auto v : now) if (!vis[v]) nw.emplace_back(v);
    now = nw;
}

void solve() {
    cin >> n;
    rep1(i, 1, n) {
	int _;
	cin >> _;
        a[i].resize(_); init(a[i]); chg[i] = 0;
    }
    rep1(i, 1, n) {
    	int id = 1;
    	rep1(j, 1, n) if (!chg[j] && a[j] < a[id]) id = j;
    	auto &now = a[id];
        for (auto v : now) printf("%d ", v), vis[v] = 1;
        now = vector <int> {inf}; chg[id] = 1;
        rep1(j, 1, n) if (!chg[j]) change(a[j]);
    } puts("");
}

int main() {
	int T;
	cin >> T;
    for (; T--; ) solve();
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N=5e5+5;
int t,n,a[N],del[N],stk[N],top,ans;
void init(){
	for(int i=1;i<=n;i++){
		del[i]=0;
	}
	ans=n;
}
int main(){
	scanf("%d",&t);
	while(t--){
		scanf("%d",&n);
		init();
		for(int i=1;i<=n;i++){
			scanf("%d",&a[i]);
		}
		top=0;
		for(int i=1;i<=n;i++){
			while(top&&a[stk[top]]<a[i]){
				top--;
			}
			stk[++top]=i;
			del[i]+=i-top;
		}
		top=0;
		for(int i=n;i>=1;i--){
			while(top&&a[stk[top]]<a[i]){
				top--;
			}
			stk[++top]=i;
			del[i]+=n-i+1-top;
		}
		for(int i=1;i<=n;i++){
			ans=min(ans,del[i]);
		}
		printf("%d\n",ans);
	}
	return 0;
}

#include <bits/stdc++.h>
#define fr1(i, a, b) for (int i = a; i <= b; i++)
#define fr2(i, a, b) for (int i = a; i >= b; i--)
using namespace std;
const int N = 1e5 + 10;
const int mod = 998244353;
int tc;
int n;
int a[N];
int dp[N];
int kmp[N];
void add(int & x, int y) {
    x += y;
    if (x >= mod) x -= mod;
}
void solve() {
    cin >> n;
    fr1(i, 1, n) cin >> a[i];
    dp[0] = 1;
    fr1(i, 1, n) dp[i] = 0;
    fr1(i, 1, n) {
        kmp[i] = i + 1;
        int poi = i + 1;
        fr2(j, i - 1, 1) {
            while (a[j] != a[poi - 1] && poi != i + 1) poi = kmp[poi];
            if (a[j] == a[poi - 1]) poi--;
            kmp[j] = poi;
        }
        fr2(j, i, 1) {
            if (kmp[j] == i + 1) add(dp[i], dp[j - 1]);
        }
    }
    cout << dp[n] << '\n';
}
int main() {
    ios::sync_with_stdio(false);
    cin >> tc;
    while (tc--) solve();
}

#include <bits/stdc++.h>
#define ll long long
using namespace std;
const int N=2e5+5;
const int M=4e5+5;
int t,n,m,fa[M];
ll s[M],ans;
vector<int> w[N],v[N];
void init(){
	for(int i=1;i<=n;i++){
		w[i].clear();
		v[i].clear();
	}
	for(int i=0;i<=(n-1)*(m-1);i++){
		fa[i]=i;
		s[i]=0;
	}
	ans=0;
}
int idx(int x,int y){
	return x>=1&&x<n&&y>=1&&y<m?(x-1)*(m-1)+y:0;
}
int find(int x){
	return fa[x]!=x?fa[x]=find(fa[x]):fa[x];
}
void merge(int a,int b){
	if(find(a)!=find(b)){
		fa[find(a)]=find(b);
	}
}
int main(){
	scanf("%d",&t);
	while(t--){
		scanf("%d%d",&n,&m);
		init();
		for(int i=1;i<n;i++){
			w[i].resize(m+1);
			for(int j=1;j<=m;j++){
				scanf("%d",&w[i][j]);
			}
		}
		for(int i=1;i<=n;i++){
			v[i].resize(m);
			for(int j=1;j<m;j++){
				scanf("%d",&v[i][j]);
			}
		}
		for(int i=1;i<n;i++){
			for(int j=1;j<m;j++){
				s[idx(i,j)]=1ll*w[i][j]-1ll*w[i][j+1]+1ll*v[i][j]-1ll*v[i+1][j];
			}
		}
		for(int i=1;i<n;i++){
			scanf("\n");
			for(int j=1;j<=m;j++){
				char p;
				scanf("%c",&p);
				if(p=='0'){
					merge(idx(i,j-1),idx(i,j));
				}
			}
		}
		for(int i=1;i<=n;i++){
			scanf("\n");
			for(int j=1;j<m;j++){
				char q;
				scanf("%c",&q);
				if(q=='0'){
					merge(idx(i-1,j),idx(i,j));
				}
			}
		}
		for(int i=1;i<=(n-1)*(m-1);i++){
			if(find(i)!=i&&find(i)!=find(0)){
				s[find(i)]+=s[i];
			}
		}
		for(int i=1;i<=(n-1)*(m-1);i++){
			if(find(i)==i&&find(i)!=find(0)){
				ans+=max(s[i],0ll);
			}
		}
		printf("%lld\n",ans);
	}
	return 0;
}

#include<bits/stdc++.h>
#define rep1(i, a, b) for(int i = a; i <= b; ++i)
#define rep2(i, a, b) for(int i = a; i >= b; --i)
#define pii pair <int, int>
#define ft first
#define sd second
#define ll long long
#define pb push_back
#define gmax(a, b) a = max(a, b)
#define gmin(a, b) a = min(a, b)
#define all(a) a.begin(), a.end()
#define debug cout << "------------------\n"
const int N = (1 << 21) + 10;
using namespace std;
int tot, ch[N][2], cnt[N], sz[N], fa[N]; ll f[N], sum[N];
int p[N], vis[N], miu[N];
void solve() {
    int n, m; cin >> n >> m;
    // get miu
    rep1(i, 0, tot) ch[i][0] = ch[i][1] = sz[i] = fa[i] = sum[i] = cnt[i] = 0;

    miu[1] = 1;
    tot = 0;
    rep1(i, 2, 2 * m) vis[i] = 0;
    rep1(i, 2, 2 * m) {
        if(!vis[i]) p[++tot] = i, miu[i] = -1;
        for(int j = 1; p[j] * i <= 2 * m && j <= tot; ++j) {
            vis[i * p[j]] = 1;
            if(i % p[j] == 0) break;
            miu[i * p[j]] = -miu[i];
        }
    }

    // get trie
    tot = 1;
    rep1(i, 0, m) {
        int nw = 1;
        rep2(j, 19, 0) {
            int &nxt = ch[nw][i >> j & 1];
            if(!nxt) nxt = ++tot, fa[nxt] = nw;
            nw = nxt;
        }
        while(nw) ++sz[nw], nw = fa[nw];
    }

    // get f(T)
    rep1(T, 1, 2 * m) {
        f[T] = 0;
        rep1(d, 1, 2 * m / T) {
            int nw = 1, bg = 0, v = (d * T) ^ m;
            rep2(i, 19, 0) {
                int x = v >> i & 1;
                if(m >> i & 1) {
                    int u = ch[nw][x ^ 1];
                    if(u) ++cnt[u], sum[u] += sz[u];
                }
                if(!ch[nw][x]) {bg = i + 1; break;}
                nw = ch[nw][x];
            }
            ll num = 0;
            if(!bg) ++cnt[nw], ++sum[nw], ++num;
            rep1(i, bg, 19) {
                nw = fa[nw];
                int x = v >> i & 1;
                if(m >> i & 1) {
                    int u = ch[nw][x ^ 1];
                    num += sz[u];
                }
                sum[nw] += num;
            }
        }
        rep1(d, 1, 2 * m / T) {
            int nw = 1, v = (d * T) ^ m;
            ll num = 0;
            rep2(i, 19, 0) {
                int x = v >> i & 1;
                num += cnt[nw];
                if(m >> i & 1) {
                    int u = ch[nw][x ^ 1];
                    if(u) f[T] += sum[u] + 1ll * num * sz[u];
                }
                nw = ch[nw][x];
                if(!nw) break;
            }
            if(nw) f[T] += sum[nw] + 1ll * num * sz[nw];
        }
        rep1(d, 1, 2 * m / T) {
            int nw = 1, bg = 0, v = (d * T) ^ m;
            rep2(i, 19, 0) {
                int x = v >> i & 1;
                int u = ch[nw][x ^ 1];
                cnt[nw] = sum[nw] = cnt[u] = sum[u] = 0;
                nw = ch[nw][x];
            }
            if(nw) cnt[nw] = sum[nw] = 0;
        }
    }

    ll ans = 0;
    rep1(d, 1, 2 * m) {
        if(n % d) continue;
        rep1(j, 1, 2 * m / d) {
            ans += miu[j] * f[j * d];
        }
    }

    // get i == j or j == k
    rep1(g, 1, 2 * m) {
        if(n % g) continue;
        int nw = 1, v = g ^ m;
        rep2(i, 19, 0) {
            int x = v >> i & 1;
            if(m >> i & 1) {
                int u = ch[nw][x ^ 1];
                ans += 2 * sz[u];
            }
            nw = ch[nw][x]; if(!nw) break;
        }
        if(nw) ans += 2;
    }

    cout << ans << '\n';
}
int main() {
    int T = 1; cin >> T;
    while(T--) solve();
    return 0;
}
